3	#[derive(Clone)]
4	pub(crate) struct KimiRankGpuContext {
5	    ctx: Arc<CudaContext>,
6	    stream: Arc<CudaStream>,
7	    device_ordinal: usize,
8	}
9	
10	// SAFETY: each Kimi rank owns one CUDA context/stream pair and the runner
11	// drives that pair from the rank worker thread.
12	unsafe impl Send for KimiRankGpuContext {}
13	unsafe impl Sync for KimiRankGpuContext {}
14	
15	impl KimiRankGpuContext {
16	    pub(crate) fn new(device_ordinal: usize) -> Result<Self> {
17	        Self::set_current_device(device_ordinal)?;
18	        let ctx = CudaContext::new(device_ordinal).with_context(|| {
19	            format!("failed to create CUDA context for device {device_ordinal}")
20	        })?;
21	        unsafe {
22	            ctx.disable_event_tracking();
23	        }
24	        let stream = ctx
25	            .new_stream()
26	            .with_context(|| format!("failed to create CUDA stream for device {device_ordinal}"))?;
27	        unsafe {
28	            ffi::cublas_init();
29	        }
30	        Ok(Self {
31	            ctx,
32	            stream,
33	            device_ordinal,
34	        })
35	    }
36	
37	    pub(crate) fn set_current(&self) -> Result<()> {
38	        Self::set_current_device(self.device_ordinal)?;
39	        self.ctx.bind_to_thread().with_context(|| {
40	            format!(
41	                "failed to bind Kimi CUDA context for device {} to current thread",
42	                self.device_ordinal
43	            )
44	        })
45	    }
46	
47	    pub(crate) fn as_device_context(&self) -> DeviceContext {
48	        DeviceContext {
49	            ctx: Arc::clone(&self.ctx),
50	            stream: Arc::clone(&self.stream),
51	            device_ordinal: self.device_ordinal,
52	        }
53	    }
54	
55	    pub(crate) fn auxiliary_device_context(&self, role: &str) -> Result<DeviceContext> {
56	        let stream = self.ctx.new_stream().with_context(|| {
57	            format!(
58	                "failed to create Kimi {role} stream for device {}",
59	                self.device_ordinal
60	            )
61	        })?;
62	        Ok(DeviceContext {
63	            ctx: Arc::clone(&self.ctx),
64	            stream,
65	            device_ordinal: self.device_ordinal,
66	        })
