230	    pub(crate) fn pack_loaded_expert_marlin_layers(
231	        &mut self,
232	        ctx: &KimiRankGpuContext,
233	        names: &KimiRankWeightNames,
234	        packed_layers: &mut BTreeSet<usize>,
235	        out: &mut Vec<KimiMoeLayerExpertMarlinWeights>,
236	    ) -> Result<()> {
237	        ensure!(
238	            self.rank == names.rank,
239	            "Kimi GPU rank {} does not match typed names rank {}",
240	            self.rank,
241	            names.rank
242	        );
243	        ctx.set_current()?;
244	        for layer in &names.layers {
245	            let KimiLayerWeightKindNames::Moe(moe) = &layer.kind else {
246	                continue;
247	            };
248	            if packed_layers.contains(&layer.layer_idx) || !self.has_all_routed_expert_raw(moe) {
249	                continue;
250	            }
251	            let weights =
252	                self.pack_moe_layer_expert_marlin_weights(ctx, names, layer.layer_idx, moe)?;
253	            weights.as_marlin_weights().validate()?;
254	            self.remove_packaged_routed_expert_raw_tensors(&[moe])?;
255	            packed_layers.insert(layer.layer_idx);
256	            out.push(weights);
257	        }
258	        Ok(())
259	    }
