329	    fn has_all_routed_expert_raw(&self, moe: &KimiMoeLayerWeightNames) -> bool {
330	        moe.routed_experts.iter().all(|expert| {
331	            has_int4_projection_raw(&self.tensors, &expert.gate_proj)
332	                && has_int4_projection_raw(&self.tensors, &expert.up_proj)
333	                && has_int4_projection_raw(&self.tensors, &expert.down_proj)
334	        })
335	    }
336	
337	    fn remove_packaged_routed_expert_raw_tensors(
338	        &mut self,
339	        moes: &[&KimiMoeLayerWeightNames],
340	    ) -> Result<()> {
341	        let mut names = Vec::new();
342	        for moe in moes {
343	            for expert in &moe.routed_experts {
344	                push_int4_projection_raw_tensor_names(&expert.gate_proj, &mut names);
345	                push_int4_projection_raw_tensor_names(&expert.up_proj, &mut names);
346	                push_int4_projection_raw_tensor_names(&expert.down_proj, &mut names);
347	            }
348	        }
349	
350	        let mut removed_bytes = 0usize;
351	        for name in &names {
352	            let tensor = self.tensors.get(name.as_str()).with_context(|| {
353	                format!("missing Kimi raw tensor {name} during package cleanup")
354	            })?;
355	            removed_bytes += tensor.bytes;
356	        }
357	        ensure!(
358	            removed_bytes <= self.total_bytes,
359	            "Kimi rank {} package cleanup would remove {} bytes from {} total bytes",
360	            self.rank,
361	            removed_bytes,
362	            self.total_bytes
363	        );
364	
365	        for name in names {
366	            let tensor = self
367	                .tensors
368	                .remove(name.as_str())
369	                .expect("validated Kimi raw tensor must exist during package cleanup");
370	            self.total_bytes -= tensor.bytes;
371	        }
372	
373	        Ok(())
374	    }
