381	        ensure!(
382	            tensor.dtype == dtype,
383	            "Kimi GPU tensor {name} dtype {:?} does not match expected {:?}",
384	            tensor.dtype,
385	            dtype
386	        );
387	        Ok(tensor)
388	    }
389	}
