447	fn validate_expert_major_projection<'a>(
448	    role: KimiInt4ProjectionRole,
449	    projections: impl IntoIterator<Item = &'a KimiInt4ProjectionGpuWeights<'a>>,
450	) -> Result<KimiExpertMajorProjectionPlan> {
451	    let projections = projections.into_iter().collect::<Vec<_>>();
452	    ensure!(
453	        !projections.is_empty(),
454	        "Kimi expert-major projection cannot be empty"
455	    );
456	    let (out_dim, in_dim) = role.dims();
457	    let packed_i32_shape = [out_dim, in_dim / 8];
458	    let scale_bf16_shape = [out_dim, in_dim / KIMI_K2_INT4_GROUP_SIZE];
459	    let mut packed_bytes = 0usize;
460	    let mut scale_bytes = 0usize;
461	    for projection in &projections {
462	        validate_raw_tensor(
463	            projection.weight_packed,
464	            Dtype::I32,
465	            &packed_i32_shape,
466	            "weight_packed",
467	        )?;
468	        validate_raw_tensor(
469	            projection.weight_scale,
470	            Dtype::BF16,
471	            &scale_bf16_shape,
472	            "weight_scale",
473	        )?;
474	        packed_bytes += projection.weight_packed.bytes;
475	        scale_bytes += projection.weight_scale.bytes;
476	    }
477	    Ok(KimiExpertMajorProjectionPlan {
478	        local_experts: projections.len(),
479	        out_dim,
480	        in_dim,
481	        packed_bytes,
482	        scale_bytes,
483	    })
484	}
485	
486	fn pack_expert_major_projection_marlin_buffers<'a>(
487	    ctx: &KimiRankGpuContext,
488	    ep_rank: usize,
489	    role: KimiInt4ProjectionRole,
490	    projections: impl IntoIterator<Item = &'a KimiInt4ProjectionGpuWeights<'a>>,
491	) -> Result<KimiExpertMajorProjectionMarlinBuffers> {
492	    let projections = projections.into_iter().collect::<Vec<_>>();
493	    let plan = validate_expert_major_projection(role, projections.iter().copied())?;
494	    let manifest = KimiInt4WeightManifest::ep8(
495	        role.kernel_role(),
496	        ep_rank,
497	        KimiInt4NibbleOrder::LowThenHigh,
498	    );
499	    manifest.validate()?;
500	    ensure!(
501	        manifest.local_experts == plan.local_experts
502	            && manifest.logical_shape.out_dim == plan.out_dim
503	            && manifest.logical_shape.in_dim == plan.in_dim
504	            && manifest.packed_shape.elements() == plan.packed_bytes
505	            && manifest.scale_shape.elements() * std::mem::size_of::<bf16>() == plan.scale_bytes,
506	        "Kimi {:?} expert-major plan does not match Marlin manifest {:?}",
507	        role,
508	        manifest
509	    );
510	
511	    let mut weight_packed_offset_binary = ctx
512	        .stream()
513	        .alloc_zeros::<u8>(manifest.packed_shape.elements())?;
514	    let mut weight_packed_marlin_uint4b8 = ctx
515	        .stream()
516	        .alloc_zeros::<u8>(manifest.packed_shape.elements())?;
517	    let mut weight_scale_checkpoint = ctx
518	        .stream()
519	        .alloc_zeros::<bf16>(manifest.scale_shape.elements())?;
520	    let mut weight_scale_marlin_permuted = ctx
521	        .stream()
522	        .alloc_zeros::<bf16>(manifest.scale_shape.elements())?;
523	
524	    copy_projection_component_to_contiguous(
525	        ctx,
526	        projections
527	            .iter()
528	            .map(|projection| projection.weight_packed),
529	        &mut weight_packed_offset_binary,
530	        plan.packed_bytes,
531	        "weight_packed",
532	    )?;
533	    kimi_marlin_int4_reorder_weight(
534	        &ctx.as_device_context(),
535	        &weight_packed_offset_binary,
536	        &mut weight_packed_marlin_uint4b8,
537	        &manifest,
538	    )?;
539	    copy_projection_component_to_typed_contiguous(
540	        ctx,
541	        projections.iter().map(|projection| projection.weight_scale),
542	        &mut weight_scale_checkpoint,
543	        plan.scale_bytes,
544	        "weight_scale",
545	    )?;
546	    kimi_marlin_int4_reorder_scale(
547	        &ctx.as_device_context(),
548	        &weight_scale_checkpoint,
549	        &mut weight_scale_marlin_permuted,
550	        &manifest,
551	    )?;
552	
553	    Ok(KimiExpertMajorProjectionMarlinBuffers {
554	        role,
555	        plan,
556	        manifest,
557	        weight_packed_marlin_uint4b8,
558	        weight_scale_marlin_permuted,
559	    })
560	}
