562	fn fuse_expert_major_w13_marlin_buffers(
563	    ctx: &KimiRankGpuContext,
564	    gate: &KimiExpertMajorProjectionMarlinBuffers,
565	    up: &KimiExpertMajorProjectionMarlinBuffers,
566	) -> Result<KimiExpertMajorW13MarlinBuffers> {
567	    ensure!(
568	        gate.role == KimiInt4ProjectionRole::Gate && up.role == KimiInt4ProjectionRole::Up,
569	        "Kimi Marlin W13 fuse expects gate/up roles, got {:?}/{:?}",
570	        gate.role,
571	        up.role
572	    );
573	    ensure!(
574	        gate.plan.local_experts == up.plan.local_experts
575	            && gate.plan.in_dim == up.plan.in_dim
576	            && gate.plan.out_dim == up.plan.out_dim
577	            && gate.plan.out_dim == KIMI_K2_EXPERT_INTERMEDIATE
578	            && gate.plan.in_dim == KIMI_K2_HIDDEN,
579	        "Kimi Marlin W13 fuse shape mismatch: gate {:?}, up {:?}",
580	        gate.plan,
581	        up.plan
582	    );
583	    let mut weight_packed_marlin_uint4b8 = ctx.stream().alloc_zeros::<u8>(
584	        gate.weight_packed_marlin_uint4b8.len() + up.weight_packed_marlin_uint4b8.len(),
585	    )?;
586	    let mut weight_scale_marlin_permuted = ctx.stream().alloc_zeros::<bf16>(
587	        gate.weight_scale_marlin_permuted.len() + up.weight_scale_marlin_permuted.len(),
588	    )?;
589	
590	    kimi_marlin_int4_fuse_w13(
591	        &ctx.as_device_context(),
592	        &gate.as_marlin_weight(),
593	        &up.as_marlin_weight(),
594	        &mut weight_packed_marlin_uint4b8,
595	        &mut weight_scale_marlin_permuted,
596	    )?;
597	
598	    let fused = KimiExpertMajorW13MarlinBuffers {
599	        local_experts: gate.plan.local_experts,
600	        in_dim: gate.plan.in_dim,
601	        intermediate_dim: gate.plan.out_dim,
602	        group_size: KIMI_K2_INT4_GROUP_SIZE,
603	        weight_packed_marlin_uint4b8,
604	        weight_scale_marlin_permuted,
605	    };
606	    fused.as_marlin_weight().validate()?;
607	    Ok(fused)
608	}
