610	fn copy_projection_component_to_contiguous<'a>(
611	    ctx: &KimiRankGpuContext,
612	    tensors: impl IntoIterator<Item = &'a KimiGpuRawTensor>,
613	    dst: &mut CudaSlice<u8>,
614	    expected_bytes: usize,
615	    component: &str,
616	) -> Result<()> {
617	    ensure!(
618	        dst.len() == expected_bytes,
619	        "Kimi expert-major {component} destination length {} does not match expected {}",
620	        dst.len(),
621	        expected_bytes
622	    );
623	    let mut offset = 0usize;
624	    for tensor in tensors {
625	        let end = offset + tensor.bytes;
626	        ensure!(
627	            end <= expected_bytes,
628	            "Kimi expert-major {component} copy would exceed destination: end {end}, expected {expected_bytes}"
629	        );
630	        ctx.stream()
631	            .memcpy_dtod(
632	                &tensor.data.slice(0..tensor.bytes),
633	                &mut dst.slice_mut(offset..end),
634	            )
635	            .with_context(|| {
636	                format!(
637	                    "failed to D2D copy Kimi expert-major {component} tensor {}",
638	                    tensor.name
639	                )
640	            })?;
641	        offset = end;
642	    }
643	    ensure!(
644	        offset == expected_bytes,
645	        "Kimi expert-major {component} copied {offset} bytes, expected {expected_bytes}"
646	    );
647	    Ok(())
648	}
649	
650	fn copy_raw_tensor_to_typed<T: DeviceRepr + ValidAsZeroBits>(
651	    ctx: &KimiRankGpuContext,
652	    tensor: &KimiGpuRawTensor,
653	) -> Result<CudaSlice<T>> {
654	    let element_bytes = std::mem::size_of::<T>();
655	    ensure!(
656	        tensor.bytes.is_multiple_of(element_bytes),
657	        "Kimi tensor {} byte size {} is not divisible by typed element size {}",
658	        tensor.name,
659	        tensor.bytes,
660	        element_bytes
661	    );
662	    let mut dst = ctx
663	        .stream()
664	        .alloc_zeros::<T>(tensor.bytes / element_bytes)?;
665	    {
666	        let (src_ptr, _src_guard) = tensor.data.device_ptr(ctx.stream());
667	        let (dst_ptr, _dst_guard) = dst.device_ptr_mut(ctx.stream());
668	        unsafe {
669	            cuda_result::memcpy_dtod_async(dst_ptr, src_ptr, tensor.bytes, ctx.stream().cu_stream())
670	        }
671	        .with_context(|| {
672	            format!(
673	                "failed to D2D copy Kimi tensor {} into typed GPU buffer",
674	                tensor.name
675	            )
676	        })?;
677	    }
678	    Ok(dst)
679	}
680	
681	fn copy_projection_component_to_typed_contiguous<'a, T: DeviceRepr>(
682	    ctx: &KimiRankGpuContext,
683	    tensors: impl IntoIterator<Item = &'a KimiGpuRawTensor>,
684	    dst: &mut CudaSlice<T>,
685	    expected_bytes: usize,
686	    component: &str,
687	) -> Result<()> {
688	    let dst_bytes = dst.len() * std::mem::size_of::<T>();
689	    ensure!(
690	        dst_bytes == expected_bytes,
691	        "Kimi expert-major {component} destination bytes {dst_bytes} does not match expected {expected_bytes}"
692	    );
693	    let mut offset = 0usize;
694	    for tensor in tensors {
695	        let end = offset + tensor.bytes;
696	        ensure!(
697	            end <= expected_bytes,
698	            "Kimi expert-major {component} copy would exceed destination: end {end}, expected {expected_bytes}"
699	        );
700	        let (src_ptr, _src_guard) = tensor.data.device_ptr(ctx.stream());
701	        let (dst_ptr, _dst_guard) = dst.device_ptr_mut(ctx.stream());
702	        // SAFETY: this is a byte-preserving D2D copy from the raw safetensors
703	        // GPU payload into a typed buffer with the same total byte count. The
704	        // dtype and shape were validated immediately before allocation.
705	        unsafe {
706	            cuda_result::memcpy_dtod_async(
707	                dst_ptr + offset as u64,
708	                src_ptr,
709	                tensor.bytes,
710	                ctx.stream().cu_stream(),
711	            )
712	        }
713	        .with_context(|| {
714	            format!(
715	                "failed to D2D copy Kimi expert-major {component} tensor {} into typed package",
716	                tensor.name
717	            )
718	        })?;
719	        offset = end;
720	    }
721	    ensure!(
722	        offset == expected_bytes,
723	        "Kimi expert-major {component} copied {offset} bytes, expected {expected_bytes}"
724	    );
725	    Ok(())
726	}
727	
728	fn validate_local_expert_name_order(
729	    rank: usize,
730	    layer_idx: usize,
731	    local_expert_range: Range<usize>,
732	    routed_experts: &[KimiRoutedExpertWeightNames],
733	) -> Result<()> {
734	    ensure!(
735	        routed_experts.len() == local_expert_range.len(),
736	        "Kimi rank {} layer {} expected {} local routed expert names, got {}",
737	        rank,
738	        layer_idx,
739	        local_expert_range.len(),
740	        routed_experts.len()
741	    );
742	    for (offset, expert) in routed_experts.iter().enumerate() {
743	        let expected = local_expert_range.start + offset;
744	        ensure!(
745	            expert.global_expert == expected,
746	            "Kimi rank {} layer {} local expert name offset {} expected global expert {}, got {}",
747	            rank,
748	            layer_idx,
749	            offset,
750	            expected,
751	            expert.global_expert
752	        );
753	    }
754	    Ok(())
755	}
756	
757	fn push_int4_projection_raw_tensor_names(
758	    projection: &KimiInt4ProjectionWeightNames,
759	    out: &mut Vec<String>,
760	) {
761	    out.push(projection.weight_packed.clone());
762	    out.push(projection.weight_scale.clone());
763	}
764	
765	fn validate_raw_tensor(
766	    tensor: &KimiGpuRawTensor,
767	    dtype: Dtype,
768	    shape: &[usize],
769	    role: &str,
770	) -> Result<()> {
771	    ensure!(
772	        tensor.dtype == dtype,
773	        "Kimi {role} tensor {} dtype {:?} does not match expected {:?}",
774	        tensor.name,
775	        tensor.dtype,
776	        dtype
777	    );
778	    ensure!(
779	        tensor.shape == shape,
780	        "Kimi {role} tensor {} shape {:?} does not match expected {:?}",
781	        tensor.name,
782	        tensor.shape,
783	        shape
784	    );
785	    let expected_bytes = shape.iter().product::<usize>() * dtype_element_bytes(dtype)?;
786	    ensure!(
787	        tensor.bytes == expected_bytes,
788	        "Kimi {role} tensor {} bytes {} does not match expected {}",
789	        tensor.name,
790	        tensor.bytes,
791	        expected_bytes
792	    );
793	    Ok(())
794	}
795

