181	    catalog: &HashMap<String, BenchEntry>,
182	) -> Result<ModelReport> {
183	    let mut by_op: BTreeMap<String, Accum> = BTreeMap::new();
184	    let mut by_site: BTreeMap<String, (String, Accum)> = BTreeMap::new();
185	    let mut missing_by_op: BTreeMap<String, MissingAccum> = BTreeMap::new();
186	    let mut coverage: BTreeMap<String, CoverageRow> = BTreeMap::new();
