197	            let (_, site_accum) = by_site
198	                .entry(site.clone())
199	                .or_insert_with(|| (call.op.clone(), Accum::default()));
200	            accumulate(site_accum, stats);
201	            coverage
202	                .entry(cov_key)
203	                .or_insert_with(|| CoverageRow {
204	                    call_site: site,
205	                    op: call.op.clone(),
206	                    status: "measured".to_string(),
207	                    calls: 0,
208	                    latency: Some(stats.clone()),
209	                    key: Some(entry.key.clone()),
210	                    reason: None,
211	                })
212	                .calls += 1;
213	        } else {
214	            let missing = missing_by_op.entry(call.op.clone()).or_default();
215	            missing.calls += 1;
216	            missing.call_sites.insert(site.clone());
217	            if missing.reason.is_none() {
218	                missing.reason.clone_from(&entry.measured.reason);
219	            }
220	            coverage
221	                .entry(cov_key)
222	                .or_insert_with(|| CoverageRow {
223	                    call_site: site,
224	                    op: call.op.clone(),
225	                    status: "missing_provider".to_string(),
226	                    calls: 0,
227	                    latency: None,
228	                    key: Some(entry.key.clone()),
229	                    reason: entry.measured.reason.clone(),
