237	    let measured_schedule_calls = by_op.values().map(|row| row.calls).sum::<usize>();
238	    let missing_schedule_calls = missing_by_op.values().map(|row| row.calls).sum::<usize>();
239	    let by_op = by_op
240	        .into_iter()
241	        .map(|(op, accum)| rollup_row(op, accum, total))
242	        .collect::<Vec<_>>();
243	    let by_call_site = by_site
244	        .into_iter()
245	        .map(|(call_site, (op, accum))| call_site_row(call_site, op, accum, total))
246	        .collect::<Vec<_>>();
