338	        .coverage
339	        .iter()
340	        .filter(|row| row.status != "measured")
341	        .count();
342	    println!("\ncoverage_missing_call_sites={missing}");
343	    if !report.missing_by_op.is_empty() {
344	        println!("missing_by_op:");
345	        for row in &report.missing_by_op {
346	            println!(
347	                "  {:34} calls={:4} call_sites={:3} reason={}",
