5	impl KimiOneTokenForwardCache {
6	    pub(super) fn from_gpu_weights(
7	        ctx: &KimiRankGpuContext,
8	        weights: &KimiRankGpuWeights,
9	        names: &KimiRankWeightNames,
10	    ) -> Result<Self> {
11	        ensure!(
12	            weights.rank == names.rank,
13	            "Kimi forward cache rank mismatch: weights={}, names={}",
14	            weights.rank,
15	            names.rank
16	        );
17	        ensure!(
18	            names.layers.len() == KIMI_K2_LAYERS,
19	            "Kimi forward cache needs {} layers, got {}",
20	            KIMI_K2_LAYERS,
21	            names.layers.len()
22	        );
23	
24	        let vocab_rows = names.plan.vocab_range.len();
25	        let token_embedding = GpuTensor::from_device_matrix_rows(
26	            raw_tensor(weights, &names.top.token_embedding)?.copy_bf16_matrix(
27	                ctx,
28	                vocab_rows,
29	                KIMI_K2_HIDDEN,
30	                "token_embedding",
31	            )?,
32	        )?;
33	        let final_norm = NormWeight::from_device_vec(
34	            raw_tensor(weights, &names.top.final_norm)?.copy_bf16_vec(
35	                ctx,
36	                KIMI_K2_HIDDEN,
37	                "final_norm",
38	            )?,
39	        )?;
40	        let lm_head = GpuTensor::from_device_matrix_rows(
41	            raw_tensor(weights, &names.top.lm_head)?.copy_bf16_matrix(
42	                ctx,
43	                vocab_rows,
44	                KIMI_K2_HIDDEN,
45	                "lm_head",
46	            )?,
47	        )?;
48	        let layers = names
49	            .layers
50	            .iter()
51	            .map(|layer| load_layer_forward_cache(ctx, weights, layer))
52	            .collect::<Result<Vec<_>>>()?;
53	
54	        Ok(Self {
55	            vocab_start: names.plan.vocab_range.start,
56	            vocab_rows,
57	            token_embedding,
58	            final_norm,
59	            lm_head,
60	            layers,
61	        })
62	    }
63	}
64	
65	impl KimiWorkerKvPool {
66	    pub(super) fn new(ctx: &DeviceContext, num_layers: usize, pool_pages: usize) -> Result<Self> {
67	        ensure!(num_layers > 0, "Kimi KV pool needs layers");
68	        ensure!(pool_pages > 0, "Kimi KV pool needs pages");
69	        // batch_size is irrelevant for buffer sizing (required_*_len depends
70	        // only on max_pages × page geometry); per-bucket arenas carry their
71	        // own layouts with the real batch dimension.
72	        let sizing = KimiMlaPagedKvLayout::separate_contiguous(pool_pages, KIMI_KV_PAGE_SIZE, 1);
73	        let mut layers = Vec::with_capacity(num_layers);
74	        for _ in 0..num_layers {
75	            layers.push(KimiWorkerMlaLayerCache {
76	                ckv_cache: ctx
77	                    .stream
78	                    .alloc_zeros::<half::bf16>(sizing.required_ckv_len()?)?,
79	                kpe_cache: ctx
80	                    .stream
81	                    .alloc_zeros::<half::bf16>(sizing.required_kpe_len()?)?,
82	            });
83	        }
84	        Ok(Self { layers })
85	    }
86	
87	    pub(super) fn layer_mut(&mut self, layer_idx: usize) -> Result<&mut KimiWorkerMlaLayerCache> {
88	        self.layers
89	            .get_mut(layer_idx)
90	            .ok_or_else(|| anyhow::anyhow!("Kimi KV pool layer cache {layer_idx} out of range"))
91	    }
