        let (tx, rx) = unbounded();
        let (startup_tx, startup_rx) = bounded::<Result<()>>(1);
        let handle = thread::Builder::new()
            .name(format!("kimi-k2-rank-{}", placement.rank))
            .spawn(move || {
                pin_rank_worker_thread(&thread_placement);
